import {NextResponse} from "next/server";import {createSupabaseServerClient} from "../../../../lib/supabase/server";
export async function POST(request:Request){if(process.env.VERCEL_ENV==="preview"||process.env.MPW_PREVIEW_MODE==="1")return NextResponse.redirect(new URL("/vendor/matches?preview=1",request.url),303);const db=await createSupabaseServerClient();const {data:{user}}=await db.auth.getUser();if(!user)return NextResponse.redirect(new URL("/vendor/login",request.url),303);const {data:v}=await db.from("vendor_profiles").select("id,plan").eq("user_id",user.id).single();if(!v||!["professional","premium"].includes(v.plan))return NextResponse.redirect(new URL("/vendor/dashboard?error=Match%20Opportunities%20require%20Pro%20or%20Premium",request.url),303);const form=await request.formData();const couple=String(form.get("couple_user_id")||"");const message=String(form.get("message")||"").trim().slice(0,300);const start=new Date();start.setUTCDate(1);start.setUTCHours(0,0,0,0);const {count}=await db.from("vendor_match_introductions").select("id",{count:"exact",head:true}).eq("vendor_id",v.id).gte("created_at",start.toISOString());const limit=v.plan==="premium"?15:5;if((count||0)>=limit)return NextResponse.redirect(new URL(`/vendor/matches?error=Monthly%20introduction%20limit%20reached`,request.url),303);const {data:cp}=await db.from("couple_profiles").select("user_id,vendor_discoverable").eq("user_id",couple).maybeSingle();if(!cp?.vendor_discoverable)return NextResponse.redirect(new URL("/vendor/matches?error=This%20couple%20is%20not%20discoverable",request.url),303);await db.from("vendor_match_introductions").insert({vendor_id:v.id,couple_user_id:couple,message});return NextResponse.redirect(new URL("/vendor/matches?message=Wave%20sent",request.url),303)}
